function a(t){return t?`¥${(t/100).toFixed(2)}`:"免费"}function f(t){if(!t)return"-";const e=new Date(t*1e3),n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}`}function s(t){if(!t)return"-";const e=new Date(t*1e3),n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())}`}function c(t){if(!t)return"-";const e=["B","KB","MB","GB"];let n=0,r=t;for(;r>=1024&&n<e.length-1;)r/=1024,n+=1;return`${r.toFixed(n?1:0)} ${e[n]}`}function d(t,e){const n={},r=o=>{let u=e[o.id]||0;for(const i of o.children||[])u+=r(i);return n[o.id]=u,u};for(const o of t||[])r(o);return n}function l(t){if(!t)return"0:00";const e=Math.floor(t/60),n=t%60;return`${e}:${String(n).padStart(2,"0")}`}export{l as a,s as b,f as d,c as f,a as m,d as r};
